let lIndex=0,lScore=0,lAnswered=false;
function renderLcm(){const x=lcmQuestions[lIndex];if(!x)return;document.querySelector('#question-number5').textContent=(lIndex+1)+' / 10';document.querySelector('#level5').textContent=dict().level[x.l];document.querySelector('#question5').textContent=x.q[lang()];const box=document.querySelector('#answers5');box.innerHTML='';x.a.forEach((answer,i)=>{const b=document.createElement('button');b.textContent=Array.isArray(answer)?answer[lang()]:answer;b.addEventListener('click',()=>chooseLcm(i,b));box.appendChild(b)});document.querySelector('#feedback5').textContent='';document.querySelector('#feedback5').className='';document.querySelector('#next5').hidden=true;lAnswered=false}
function chooseLcm(choice,button){if(lAnswered)return;lAnswered=true;const x=lcmQuestions[lIndex],ok=choice===x.c;if(ok)lScore++;document.querySelector('#score5').textContent=lScore;[...document.querySelectorAll('#answers5 button')].forEach((b,i)=>{b.disabled=true;if(i===x.c)b.classList.add('correct-answer')});if(!ok)button.classList.add('wrong-answer');const f=document.querySelector('#feedback5');f.textContent=(ok?dict().correct:dict().wrong)+' '+x.e[lang()];f.className=ok?'correct':'wrong';const n=document.querySelector('#next5');n.textContent=lIndex===9?dict().finish:dict().next;n.hidden=false}
function nextLcm(){if(lIndex<9){lIndex++;renderLcm()}else{document.querySelector('#question-card5').hidden=true;document.querySelector('#result5').hidden=false;document.querySelector('#result-title5').textContent=dict().resultTitle;document.querySelector('#result-text5').textContent=lScore+'/10 — '+(lScore>=8?dict().resultGood:lScore>=5?dict().resultMid:dict().resultLow);document.querySelector('#restart5').textContent=dict().restart}}
function restartLcm(){lIndex=0;lScore=0;document.querySelector('#score5').textContent='0';document.querySelector('#result5').hidden=true;document.querySelector('#question-card5').hidden=false;renderLcm()}
